197	        li.appendChild(due);
198	      }
199	      li.appendChild(del);
200	      list.appendChild(li);
201	    });
202	  }
203	
204	  var todos = load();
205	  var filter = 'all';
206	  var renderedDay = '';
207	  var filterButtons = Array.prototype.slice.call(document.querySelectorAll('[data-filter]'));
208	
209	  filterButtons.forEach(function (btn) {
210	    btn.addEventListener('click', function () {
211	      filter = btn.dataset.filter;
212	      render();
213	    });
214	  });
215	
216	  searchInput.addEventListener('input', render);
217	
218	  document.querySelector('[data-testid="bulk-mark-all"]').addEventListener('click', function () {
219	    todos = TodoLogic.markAllComplete(todos);
220	    save();
221	    render();
222	  });
223	
224	  document.querySelector('[data-testid="bulk-clear-completed"]').addEventListener('click', function () {
225	    todos = TodoLogic.clearCompleted(todos);
226	    save();
227	    render();
228	  });
229	
230	  form.addEventListener('submit', function (event) {
231	    event.preventDefault();
232	    var text = input.value.trim();
233	    if (!text) return;
234	    var todo = {
235	      id: newId(), text: text, createdAt: Date.now(), completed: false,
236	      priority: TodoLogic.normalizePriority(priorityInput.value)
237	    };
238	    if (/^\d{4}-\d{2}-\d{2}$/.test(dueInput.value)) todo.due = dueInput.value;
239	    todos.push(todo);
240	    save();
241	    render();
242	    input.value = '';
243	    dueInput.value = '';
244	    priorityInput.value = 'med';
245	    input.focus();
246	  });
247	
248	  // Re-render when the local day changes so overdue flags stay current.
249	  setInterval(function () {
250	    if (TodoLogic.localToday() !== renderedDay) render();
251	  }, 60000);
252	
253	  render();
254	})();
255	</script>
256	</body>
257	</html>
